CREATE TABLE IF NOT EXISTS public.live_checkout_intents(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id),
 session_id uuid NOT NULL REFERENCES live_sessions(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '60 minutes',
 UNIQUE(user_id,session_id));
ALTER TABLE live_checkout_intents ENABLE ROW LEVEL SECURITY;
GRANT ALL ON live_checkout_intents TO service_role;
CREATE OR REPLACE FUNCTION public.get_live_checkout_intent(p_user_id uuid,p_session_id uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE out_id uuid;
BEGIN
 INSERT INTO live_checkout_intents(user_id,session_id) VALUES(p_user_id,p_session_id)
 ON CONFLICT(user_id,session_id) DO UPDATE SET id=CASE WHEN live_checkout_intents.expires_at<now() THEN gen_random_uuid() ELSE live_checkout_intents.id END,
 expires_at=CASE WHEN live_checkout_intents.expires_at<now() THEN now()+interval '60 minutes' ELSE live_checkout_intents.expires_at END
 RETURNING id INTO out_id;
 RETURN out_id;
END $$;
REVOKE ALL ON FUNCTION get_live_checkout_intent(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION get_live_checkout_intent(uuid,uuid) TO service_role;
ALTER TABLE live_room_access ADD COLUMN IF NOT EXISTS first_joined_at timestamptz;
create or replace function public.apply_paid_live_checkout(p_checkout_id text,p_user_id uuid,p_session_id uuid,p_gross_cents integer,p_fee_cents integer)
returns void language plpgsql security definer set search_path = public as $$
declare v_trainer text;
begin
  PERFORM pg_advisory_xact_lock(hashtext(p_session_id::text||p_user_id::text));
  if p_gross_cents<>500 OR p_fee_cents<0 OR p_gross_cents < p_fee_cents then raise exception 'Invalid fees'; end if;
  select trainer_id::text into v_trainer from public.live_sessions where id=p_session_id AND status IN ('scheduled','live');
  if v_trainer is null then raise exception 'Unknown session'; end if;
  insert into public.checkout_payment_state(checkout_id,kind,user_id,gross_cents,fee_cents)
  values(p_checkout_id,'live',p_user_id,p_gross_cents,p_fee_cents)
  on conflict do nothing;
  if not found then return; end if;
  IF EXISTS(SELECT 1 FROM live_room_access WHERE session_id=p_session_id AND user_id=p_user_id AND status='paid') THEN
   INSERT INTO refund_jobs(checkout_id,reason) VALUES(p_checkout_id,'duplicate_class_payment') ON CONFLICT DO NOTHING; RETURN;
  END IF;
  insert into public.live_room_access(session_id,user_id,stripe_checkout_session_id,status)
  values(p_session_id,p_user_id,p_checkout_id,'paid')
  on conflict(session_id,user_id) do update set status='paid',stripe_checkout_session_id=excluded.stripe_checkout_session_id;
  insert into public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
  values(v_trainer,'live',p_checkout_id,p_gross_cents,p_fee_cents,p_gross_cents-p_fee_cents,50,(p_gross_cents-p_fee_cents)/2)
  on conflict(ref) do nothing;
end $$;

CREATE OR REPLACE FUNCTION public.redeem_paid_live_token(p_user_id uuid,p_session_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_trainer uuid; v_balance integer; v_lot public.wallet_token_lots%ROWTYPE; v_net integer; v_gross integer; v_fee integer; unit integer;
BEGIN
 SELECT trainer_id INTO v_trainer FROM public.live_sessions WHERE id=p_session_id AND starts_at>now()-interval '4 hours'
   AND starts_at<now()+interval '1 day' AND status IN ('scheduled','live');
 IF v_trainer IS NULL THEN RAISE EXCEPTION 'Class unavailable'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.live_room_access WHERE user_id=p_user_id AND session_id=p_session_id AND status='paid') THEN RETURN; END IF;
 SELECT coalesce(tokens,0) INTO v_balance FROM public.profiles WHERE id=p_user_id;
 IF v_balance<1 THEN RAISE EXCEPTION 'No available tokens'; END IF;
 SELECT * INTO v_lot FROM public.wallet_token_lots WHERE user_id=p_user_id AND remaining>0
 ORDER BY created_at,id LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'No verified purchased tokens available'; END IF;
 unit=v_lot.purchased-v_lot.remaining;
 v_gross=floor(v_lot.gross_cents::numeric*(unit+1)/v_lot.purchased)-floor(v_lot.gross_cents::numeric*unit/v_lot.purchased);
 v_fee=floor(v_lot.fee_cents::numeric*(unit+1)/v_lot.purchased)-floor(v_lot.fee_cents::numeric*unit/v_lot.purchased);
 v_net=v_gross-v_fee;
 UPDATE public.wallet_token_lots SET remaining=remaining-1 WHERE id=v_lot.id;
 UPDATE public.profiles SET tokens=tokens-1 WHERE id=p_user_id;
 INSERT INTO public.live_room_access(session_id,user_id,status,wallet_lot_id) VALUES(p_session_id,p_user_id,'paid',v_lot.id)
 ON CONFLICT(session_id,user_id) DO UPDATE SET status='paid',wallet_lot_id=excluded.wallet_lot_id;
 INSERT INTO public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
 VALUES(v_trainer::text,'live','wallet:'||p_session_id::text||':'||p_user_id::text,
   v_gross,v_fee,v_net,50,floor(v_net*0.5)::integer)
 ON CONFLICT(ref) DO NOTHING;
END $$;


-- FILE: 0042_booking_reservations.sql
CREATE OR REPLACE FUNCTION public.hold_private_booking(p_trainer_id uuid,p_member_id uuid,p_day date,p_time text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE out_id uuid; start_time timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p_trainer_id::text||p_day::text));
 start_time=(p_day::text||' '||p_time)::timestamp AT TIME ZONE 'America/Chicago';
 IF p_member_id=p_trainer_id OR start_time<=now() OR p_day>current_date+365
 OR p_time NOT IN ('07:00','09:00','12:00','15:00','19:00') OR NOT trainer_is_eligible(p_trainer_id,false)
 THEN RAISE EXCEPTION 'Invalid private booking'; END IF;
 DELETE FROM private_booking_holds WHERE expires_at<now();
 SELECT id INTO out_id FROM private_booking_holds WHERE trainer_id=p_trainer_id AND member_id=p_member_id AND day=p_day AND time=p_time;
 IF FOUND THEN RETURN out_id; END IF;
 IF EXISTS(SELECT 1 FROM trainer_busy WHERE trainer_id=p_trainer_id::text AND day=p_day AND (time=p_time OR time='ALL'))
 OR EXISTS(SELECT 1 FROM live_sessions WHERE trainer_id=p_trainer_id AND status IN ('scheduled','live')
  AND starts_at<start_time+interval '1 hour' AND starts_at+minutes*interval '1 minute'>start_time)
 OR EXISTS(SELECT 1 FROM private_session_access WHERE trainer_id=p_trainer_id AND status='paid'
  AND starts_at<start_time+interval '1 hour' AND starts_at+interval '1 hour'>start_time)
 THEN RAISE EXCEPTION 'Trainer unavailable'; END IF;
 INSERT INTO private_booking_holds(trainer_id,member_id,day,time) VALUES(p_trainer_id,p_member_id,p_day,p_time) RETURNING id INTO out_id;
 RETURN out_id;
END $$;
-- A new live class cannot take a time already reserved in a private checkout or paid booking.
CREATE OR REPLACE FUNCTION public.protect_class_calendar()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.starts_at=OLD.starts_at THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtext(NEW.trainer_id::text||(NEW.starts_at AT TIME ZONE 'America/Chicago')::date::text));
 IF EXISTS(SELECT 1 FROM private_booking_holds WHERE trainer_id=NEW.trainer_id AND expires_at>now()
  AND (day::text||' '||time)::timestamp AT TIME ZONE 'America/Chicago'<NEW.starts_at+NEW.minutes*interval '1 minute'
  AND ((day::text||' '||time)::timestamp AT TIME ZONE 'America/Chicago')+interval '1 hour'>NEW.starts_at)
 OR EXISTS(SELECT 1 FROM private_session_access WHERE trainer_id=NEW.trainer_id AND status='paid'
  AND starts_at<NEW.starts_at+NEW.minutes*interval '1 minute' AND starts_at+interval '1 hour'>NEW.starts_at)
 THEN RAISE EXCEPTION 'Time conflicts with a private reservation'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS protect_class_calendar ON live_sessions;
CREATE TRIGGER protect_class_calendar BEFORE INSERT OR UPDATE OF starts_at ON live_sessions FOR EACH ROW EXECUTE FUNCTION protect_class_calendar();


-- FILE: 0043_ad_measurements.sql
-- Measurements are authenticated, deduplicated, and NEVER themselves create payable earnings.
ALTER TABLE water_break_impressions ADD COLUMN IF NOT EXISTS viewer_id uuid REFERENCES auth.users(id);
ALTER TABLE water_break_impressions ADD COLUMN IF NOT EXISTS impression_day date NOT NULL DEFAULT current_date;
CREATE UNIQUE INDEX IF NOT EXISTS measured_break_per_day ON water_break_impressions(viewer_id,video_id,break_second,impression_day);
DROP FUNCTION IF EXISTS public.record_water_break_impression(uuid,uuid,integer,uuid);
CREATE OR REPLACE FUNCTION public.record_water_break_impression(p_campaign_id uuid,p_video_id uuid,p_break_second integer,p_playback_id uuid,p_viewer_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM water_break_campaigns WHERE id=p_campaign_id AND active
 AND (start_at IS NULL OR start_at<=now()) AND (end_at IS NULL OR end_at>=now())) THEN RAISE EXCEPTION 'Inactive campaign'; END IF;
 IF NOT EXISTS(SELECT 1 FROM trainer_videos WHERE id=p_video_id AND review_status='approved' AND p_break_second=ANY(breaks))
 THEN RAISE EXCEPTION 'Unapproved workout or break'; END IF;
 INSERT INTO water_break_impressions(campaign_id,video_id,break_second,playback_id,viewer_id)
 VALUES(p_campaign_id,p_video_id,p_break_second,p_playback_id,p_viewer_id) ON CONFLICT DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION record_water_break_impression(uuid,uuid,integer,uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION record_water_break_impression(uuid,uuid,integer,uuid,uuid) TO service_role;


-- FILE: 0044_contract_hardening.sql
CREATE OR REPLACE FUNCTION public.valid_iso_date(p_value text)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN RETURN p_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' AND (p_value::date)::text=p_value;
EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
-- Program mutations must never associate someone else's video, even using direct REST writes.
DROP POLICY IF EXISTS "program workouts insert" ON trainer_program_workouts;
DROP POLICY IF EXISTS "program workouts update" ON trainer_program_workouts;
DROP POLICY IF EXISTS program_workouts_owner_insert ON trainer_program_workouts;
CREATE POLICY program_workouts_owner_insert ON trainer_program_workouts FOR INSERT TO authenticated WITH CHECK(
 EXISTS(SELECT 1 FROM trainer_programs p JOIN trainer_videos v ON v.id=video_id
  WHERE p.id=program_id AND p.trainer_id=auth.uid() AND v.user_id=auth.uid() AND v.review_status='approved'));
DROP POLICY IF EXISTS program_workouts_owner_update ON trainer_program_workouts;
CREATE POLICY program_workouts_owner_update ON trainer_program_workouts FOR UPDATE TO authenticated USING(
 EXISTS(SELECT 1 FROM trainer_programs WHERE id=program_id AND trainer_id=auth.uid())) WITH CHECK(
 EXISTS(SELECT 1 FROM trainer_programs p JOIN trainer_videos v ON v.id=video_id
  WHERE p.id=program_id AND p.trainer_id=auth.uid() AND v.user_id=auth.uid() AND v.review_status='approved'));

CREATE OR REPLACE FUNCTION public.trainer_is_eligible(p_user_id uuid,p_live boolean DEFAULT false)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT EXISTS(SELECT 1 FROM profiles WHERE id=p_user_id AND role='trainer')
 AND EXISTS(SELECT 1 FROM certifications WHERE user_id=p_user_id AND status='verified'
  AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND verified_by<>user_id
  AND public.valid_iso_date(expires) AND expires>=to_char(current_date,'YYYY-MM-DD')
  AND name ~* '\m(CPR|cardiopulmonary resuscitation)\M')
 AND EXISTS(SELECT 1 FROM certifications WHERE user_id=p_user_id AND status='verified'
  AND verified_at IS NOT NULL AND verified_by IS NOT NULL AND verified_by<>user_id
  AND public.valid_iso_date(expires) AND expires>=to_char(current_date,'YYYY-MM-DD')
  AND name ~* '\m(AED|automated external defibrillator)\M')
 AND (NOT p_live OR (SELECT count(*) FROM trainer_videos WHERE user_id=p_user_id AND review_status='approved')>=5)
$$;


-- FILE: 0045_payment_disputes.sql
-- Signed chargeback events suspend access and preserve a recoverable, auditable ledger.
CREATE TABLE IF NOT EXISTS payment_disputes(id text PRIMARY KEY,checkout_id text NOT NULL,status text NOT NULL CHECK(status IN ('open','won','lost')),
 wallet_remaining integer,wallet_revoked integer,reconciled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE payment_disputes ENABLE ROW LEVEL SECURITY;
GRANT ALL ON payment_disputes TO service_role;
ALTER TABLE wallet_token_lots ADD COLUMN IF NOT EXISTS frozen boolean NOT NULL DEFAULT false;
ALTER TABLE trainer_earnings ADD COLUMN IF NOT EXISTS adjustment_for uuid REFERENCES trainer_earnings(id);
CREATE OR REPLACE FUNCTION public.apply_payment_dispute(p_id text,p_checkout_id text,p_status text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v checkout_payment_state%ROWTYPE; prior payment_disputes%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p_checkout_id));
 SELECT * INTO prior FROM payment_disputes WHERE id=p_id FOR UPDATE;
 IF FOUND AND prior.status IN ('won','lost') THEN RETURN; END IF;
 INSERT INTO payment_disputes(id,checkout_id,status) VALUES(p_id,p_checkout_id,p_status)
 ON CONFLICT(id) DO UPDATE SET status=p_status;
 SELECT * INTO v FROM checkout_payment_state WHERE checkout_id=p_checkout_id FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 IF p_status='open' OR p_status='lost' THEN
  UPDATE payment_disputes SET wallet_remaining=coalesce(wallet_remaining,(SELECT remaining FROM wallet_token_lots WHERE id=p_checkout_id)),
   wallet_revoked=coalesce(wallet_revoked,(SELECT revoked FROM wallet_token_lots WHERE id=p_checkout_id)) WHERE id=p_id;
  UPDATE wallet_token_lots SET frozen=true WHERE id=p_checkout_id;
  UPDATE profiles SET tokens=(SELECT coalesce(sum(remaining),0) FROM wallet_token_lots WHERE user_id=v.user_id AND NOT frozen) WHERE id=v.user_id;
  UPDATE private_session_access SET status='cancelled' WHERE checkout_id=p_checkout_id AND status='paid';
  UPDATE live_room_access SET status='cancelled' WHERE (stripe_checkout_session_id=p_checkout_id OR wallet_lot_id=p_checkout_id) AND status='paid';
  UPDATE trainer_earnings SET reversal_target_cents=payout_cents,
   status=CASE WHEN transfer_id IS NULL AND operation_key IS NULL THEN 'refunded' ELSE 'reversal_due' END
   WHERE ref=p_checkout_id OR ref IN(SELECT 'wallet:'||session_id::text||':'||user_id::text FROM live_room_access WHERE wallet_lot_id=p_checkout_id);
 END IF;
END $$;
CREATE OR REPLACE FUNCTION public.restore_won_disputes()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE d payment_disputes%ROWTYPE; v checkout_payment_state%ROWTYPE; e trainer_earnings%ROWTYPE;
 desired integer; actual integer; refund_target integer;
BEGIN
 FOR d IN SELECT * FROM payment_disputes WHERE status='won' AND NOT reconciled FOR UPDATE LOOP
  IF EXISTS(SELECT 1 FROM trainer_earnings WHERE operation_key IS NOT NULL AND
   (ref=d.checkout_id OR ref IN(SELECT 'wallet:'||session_id::text||':'||user_id::text FROM live_room_access WHERE wallet_lot_id=d.checkout_id))) THEN CONTINUE; END IF;
  SELECT * INTO v FROM checkout_payment_state WHERE checkout_id=d.checkout_id;
  IF NOT FOUND THEN CONTINUE; END IF;
  UPDATE wallet_token_lots SET frozen=false WHERE id=d.checkout_id;
  UPDATE profiles SET tokens=(SELECT coalesce(sum(remaining),0) FROM wallet_token_lots WHERE user_id=v.user_id AND NOT frozen) WHERE id=v.user_id;
  IF v.refunded_cents=0 THEN
   UPDATE private_session_access SET status='paid' WHERE checkout_id=d.checkout_id AND status='cancelled';
   UPDATE live_room_access a SET status='paid' WHERE (stripe_checkout_session_id=d.checkout_id OR wallet_lot_id=d.checkout_id)
    AND status='cancelled' AND EXISTS(SELECT 1 FROM live_sessions WHERE id=a.session_id AND status IN ('scheduled','live'));
  END IF;
  FOR e IN SELECT * FROM trainer_earnings WHERE ref=d.checkout_id OR
    ref IN(SELECT 'wallet:'||session_id::text||':'||user_id::text FROM live_room_access WHERE wallet_lot_id=d.checkout_id) FOR UPDATE LOOP
   refund_target=CASE WHEN v.gross_cents>0 THEN floor(e.payout_cents::numeric*v.refunded_cents/v.gross_cents) ELSE e.payout_cents END;
   desired=e.payout_cents-refund_target;
   IF e.transfer_id IS NULL THEN
    UPDATE trainer_earnings SET reversal_target_cents=refund_target,status=CASE WHEN desired>0 THEN 'pending' ELSE 'refunded' END WHERE id=e.id;
   ELSE
    actual=e.payout_cents-e.withheld_cents-e.transfer_reversed_cents;
    UPDATE trainer_earnings SET reversal_target_cents=greatest(refund_target,e.withheld_cents+e.transfer_reversed_cents),
      status=CASE WHEN refund_target>e.withheld_cents+e.transfer_reversed_cents THEN 'reversal_due' ELSE 'paid' END WHERE id=e.id;
    IF desired>actual THEN
     INSERT INTO trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents,adjustment_for)
     VALUES(e.trainer_slug,e.source,'dispute-recovery:'||d.id||':'||e.id::text,desired-actual,0,desired-actual,100,desired-actual,e.id)
     ON CONFLICT(ref) DO NOTHING;
    END IF;
   END IF;
  END LOOP;
  UPDATE payment_disputes SET reconciled=true WHERE id=d.id;
 END LOOP;
END $$;
REVOKE ALL ON FUNCTION apply_payment_dispute(text,text,text),restore_won_disputes() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION apply_payment_dispute(text,text,text),restore_won_disputes() TO service_role;

CREATE OR REPLACE FUNCTION public.redeem_paid_live_token(p_user_id uuid,p_session_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_trainer uuid; v_balance integer; v_lot public.wallet_token_lots%ROWTYPE; v_net integer; v_gross integer; v_fee integer; unit integer;
BEGIN
 SELECT trainer_id INTO v_trainer FROM public.live_sessions WHERE id=p_session_id AND starts_at>now()-interval '4 hours'
   AND starts_at<now()+interval '1 day' AND status IN ('scheduled','live');
 IF v_trainer IS NULL THEN RAISE EXCEPTION 'Class unavailable'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_user_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.live_room_access WHERE user_id=p_user_id AND session_id=p_session_id AND status='paid') THEN RETURN; END IF;
 SELECT coalesce(tokens,0) INTO v_balance FROM public.profiles WHERE id=p_user_id;
 IF v_balance<1 THEN RAISE EXCEPTION 'No available tokens'; END IF;
 SELECT * INTO v_lot FROM public.wallet_token_lots WHERE user_id=p_user_id AND remaining>0 AND NOT frozen
 ORDER BY created_at,id LIMIT 1 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'No verified purchased tokens available'; END IF;
 unit=v_lot.purchased-v_lot.remaining;
 v_gross=floor(v_lot.gross_cents::numeric*(unit+1)/v_lot.purchased)-floor(v_lot.gross_cents::numeric*unit/v_lot.purchased);
 v_fee=floor(v_lot.fee_cents::numeric*(unit+1)/v_lot.purchased)-floor(v_lot.fee_cents::numeric*unit/v_lot.purchased);
 v_net=v_gross-v_fee;
 UPDATE public.wallet_token_lots SET remaining=remaining-1 WHERE id=v_lot.id;
 UPDATE public.profiles SET tokens=tokens-1 WHERE id=p_user_id;
 INSERT INTO public.live_room_access(session_id,user_id,status,wallet_lot_id) VALUES(p_session_id,p_user_id,'paid',v_lot.id)
 ON CONFLICT(session_id,user_id) DO UPDATE SET status='paid',wallet_lot_id=excluded.wallet_lot_id;
 INSERT INTO public.trainer_earnings(trainer_slug,source,ref,gross_cents,fee_cents,net_cents,share_pct,payout_cents)
 VALUES(v_trainer::text,'live','wallet:'||p_session_id::text||':'||p_user_id::text,
   v_gross,v_fee,v_net,50,floor(v_net*0.5)::integer)
 ON CONFLICT(ref) DO NOTHING;
END $$;

CREATE OR REPLACE FUNCTION public.apply_checkout_refund(p_checkout_id text,p_refund_cents integer,p_fully_refunded boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.checkout_payment_state%ROWTYPE; e public.trainer_earnings%ROWTYPE; target integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext(p_checkout_id));
 SELECT * INTO v FROM public.checkout_payment_state WHERE checkout_id=p_checkout_id FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 IF p_refund_cents < 0 OR p_refund_cents > v.gross_cents THEN RAISE EXCEPTION 'Bad refund amount'; END IF;
 IF p_refund_cents <= v.refunded_cents THEN RETURN; END IF;
 UPDATE public.checkout_payment_state SET refunded_cents=p_refund_cents WHERE checkout_id=p_checkout_id;
 IF v.kind='tokens' THEN
   UPDATE wallet_token_lots SET remaining=greatest(0,remaining-
     (ceil(purchased::numeric*p_refund_cents/v.gross_cents)::integer-revoked)),
     revoked=ceil(purchased::numeric*p_refund_cents/v.gross_cents)::integer WHERE id=p_checkout_id;
   UPDATE profiles SET tokens=(SELECT coalesce(sum(remaining),0) FROM wallet_token_lots WHERE user_id=v.user_id AND NOT frozen) WHERE id=v.user_id;
   -- Any refund against a spent lot suspends its paid entitlements pending reconciliation.
   UPDATE live_room_access SET status='refunded' WHERE wallet_lot_id=p_checkout_id;
   UPDATE trainer_earnings SET reversal_target_cents=payout_cents,
    status=CASE WHEN transfer_id IS NULL THEN 'refunded' ELSE 'reversal_due' END
    WHERE ref IN(SELECT 'wallet:'||session_id::text||':'||user_id::text FROM live_room_access WHERE wallet_lot_id=p_checkout_id);
 END IF;
 IF p_fully_refunded THEN
   IF v.kind='booking' THEN
     DELETE FROM public.trainer_busy WHERE source='booked' AND (trainer_id,day,time) IN (
       SELECT b->>'trainerId',(b->>'date')::date,b->>'time' FROM public.profiles p,
       LATERAL jsonb_array_elements(coalesce(p.bookings,'[]'::jsonb)) b
       WHERE p.id=v.user_id AND b->>'id'=p_checkout_id
     );
     UPDATE public.profiles SET bookings=(SELECT coalesce(jsonb_agg(b),'[]'::jsonb)
       FROM jsonb_array_elements(coalesce(bookings,'[]'::jsonb)) b WHERE b->>'id'<>p_checkout_id)
       WHERE id=v.user_id;
     UPDATE public.private_session_access SET status='refunded' WHERE checkout_id=p_checkout_id;
   ELSIF v.kind='live' THEN
     UPDATE public.live_room_access SET status='refunded' WHERE stripe_checkout_session_id=p_checkout_id;
   END IF;
 END IF;
 SELECT * INTO e FROM public.trainer_earnings WHERE ref=p_checkout_id FOR UPDATE;
 IF FOUND THEN
   target := CASE WHEN v.gross_cents>0 THEN
     floor(e.payout_cents::numeric * p_refund_cents / v.gross_cents)::integer ELSE e.payout_cents END;
   IF e.transfer_id IS NOT NULL THEN
     UPDATE public.trainer_earnings SET reversal_target_cents=target,
       status=CASE WHEN target>transfer_reversed_cents THEN 'reversal_due' ELSE 'paid' END
       WHERE id=e.id;
   ELSE
     -- No transfer exists. Keep original payout for historical reconciliation, exclude fully refunded work.
     UPDATE public.trainer_earnings SET status=CASE WHEN operation_key IS NOT NULL THEN 'transferring' WHEN p_fully_refunded THEN 'refunded' ELSE 'pending' END,
       reversal_target_cents=target WHERE id=e.id;
   END IF;
 END IF;
END $$;


-- FILE: 0046_recording_shutdown.sql
GRANT SELECT ON live_recordings TO authenticated;
DROP POLICY IF EXISTS recording_admin_read ON live_recordings;
CREATE POLICY recording_admin_read ON live_recordings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE live_sessions ADD COLUMN IF NOT EXISTS recording_enabled boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.room_shutdown_jobs(session_id uuid PRIMARY KEY REFERENCES live_sessions(id),completed_at timestamptz);
ALTER TABLE room_shutdown_jobs ENABLE ROW LEVEL SECURITY;
GRANT ALL ON room_shutdown_jobs TO service_role;
CREATE OR REPLACE FUNCTION public.queue_room_shutdown()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF NEW.status IN ('ended','cancelled') THEN INSERT INTO room_shutdown_jobs(session_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS room_shutdown ON live_sessions;
